package capture_test
import (
 "context"
 "os"
 "path/filepath"
 "testing"
 "time"
 "agenticlens/internal/adapters/capture"
)
func TestDataReviewDanglingLedgerLockIdentity(t *testing.T) {
 dir:=t.TempDir()
 target:=filepath.Join(dir,"ledger.json")
 alias:=filepath.Join(dir,"alias.json")
 if err:=os.Symlink(target,alias);err!=nil {t.Fatal(err)}
 first,err:=capture.AcquirePublication(context.Background(),alias)
 if err!=nil {t.Fatal(err)}
 defer first.Close()
 ctx,cancel:=context.WithTimeout(context.Background(),100*time.Millisecond);defer cancel()
 second,err:=capture.AcquirePublication(ctx,target)
 if err==nil {second.Close();t.Fatal("two simultaneous publication owners for same physical absent ledger through dangling alias")}
}

func TestDataReviewExistingAndDirectoryAliasControls(t *testing.T) {
 for _,existing:=range []bool{false,true} {
  dir:=t.TempDir();target:=filepath.Join(dir,"ledger.json");alias:=filepath.Join(dir,"alias.json")
  if existing {if err:=os.WriteFile(target,[]byte("accepted"),0600);err!=nil{t.Fatal(err)};if err:=os.Symlink(target,alias);err!=nil{t.Fatal(err)}} else {
   aliasDir:=filepath.Join(t.TempDir(),"alias");if err:=os.Symlink(dir,aliasDir);err!=nil{t.Fatal(err)};alias=filepath.Join(aliasDir,"ledger.json")
  }
  first,err:=capture.AcquirePublication(context.Background(),alias);if err!=nil{t.Fatal(err)}
  ctx,cancel:=context.WithTimeout(context.Background(),100*time.Millisecond)
  second,err:=capture.AcquirePublication(ctx,target)
  cancel();if err==nil{second.Close();first.Close();t.Fatal("control split")};first.Close()
 }
}

