			lock, err := capture.AcquireWorker(f.state)
			if err != nil || lock == nil {
				t.Fatalf("disabled worker retained ownership: %v", err)
			}
			lock.Close()
			// Explicit manual recovery remains supported with the accepted source binding.
			f.output = output
