	set("old-state")
	out, err = runCaptureNative(t, f.project, "", "capture", "install", "--repo", f.project, "--source", "codex", "--store", f.store, "--binary", cliBinaryPath)
	if err != nil {
		t.Fatalf("safe reinstall: %v %s", err, out)
