 family, err := codex.DiscoverRolloutPaths(codex.DiscoveryOptions{CodexHome:rawHome, Nonce:"physical-nonce"})
 if err != nil || len(family)!=1 || family[0]!=want { t.Fatalf("physical home family=%v err=%v",family,err) }
}

